import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Inject,
  AfterViewChecked,
  OnDestroy,
  ElementRef,
  OnChanges,
  SimpleChanges,
  Output,
  EventEmitter,
  PLATFORM_ID
} from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { I18nService } from '@honoregaming/i18n';

// BR global object to control widget
declare var SIR;

const configuration = {
  pitchLogo: 'https://storage-prod.sporty-tech.net/assets/congobet/lmt/pitch.png',
  goalBannerImage: 'https://storage-prod.sporty-tech.net/assets/congobet/lmt/sideline.png',
  logo: ['https://storage-prod.sporty-tech.net/assets/congobet/lmt/panels.svg'],
  customBrandColor: '#006CA7',
  goalBannerCustomBgColor: '#F37006'
};

@Component({
  selector: 'hg-live-match-tracker',
  templateUrl: './live-match-tracker.component.html',
  styleUrls: ['./live-match-tracker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LiveMatchTrackerComponent implements OnInit, AfterViewChecked, OnDestroy, OnChanges {
  @Input()
  sourceRef: string;

  @Output()
  close = new EventEmitter();

  @Input()
  brSubscriptionId: string;

  public cleanedSourceRef: string;

  constructor(
    @Inject(DOCUMENT) private document,
    private i18nService: I18nService,
    private elementRef: ElementRef,
    @Inject(PLATFORM_ID) private platformId
  ) {}

  ngOnInit() {
    if (isPlatformBrowser(this.platformId) && typeof SIR === 'undefined' && typeof window !== 'undefined') {
      window['SIR'] = { o: { language: this.i18nService.currentLanguageCode } };
      const script = this.document.createElement('script');
      script.src = `https://widgets.sir.sportradar.com/${this.brSubscriptionId}/widgetloader`;
      script.async = 1;
      script.type = 'application/javascript';
      this.document.querySelector('head').appendChild(script);
    }

    const container: HTMLElement = this.elementRef.nativeElement.querySelector('div');
    Object.keys(configuration).forEach(x => {
      let key = x;
      key = key.charAt(0).toUpperCase() + key.slice(1);
      key = 'sr' + key;
      container.dataset[key] = configuration[x];
    });
  }

  ngOnDestroy(): void {
    SIR('removeWidget', this.elementRef.nativeElement.querySelector('div'));
  }

  ngAfterViewChecked() {
    if (typeof SIR === 'function') {
      SIR('check');
    }
  }

  ngOnChanges(_changes: SimpleChanges): void {
    this.cleanedSourceRef = this.sourceRef.replace('BR-', '');
  }
}
