import { Component, ChangeDetectionStrategy, Output, EventEmitter, Input } from '@angular/core';

@Component({
  selector: 'hg-score-widget-warning-data',
  templateUrl: './score-widget-warning-data.component.html',
  styleUrls: ['./score-widget-warning-data.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ScoreWidgetWarningDataComponent {
  @Output()
  close = new EventEmitter<boolean>();

  @Input()
  isLive: boolean;

  @Input()
  warnOnDataConsumption: boolean = false;
}
