import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { ChangeDetectorRef, SimpleChanges } from '@angular/core';
import { PLATFORM_ID } from '@angular/core';
import { OnDestroy } from '@angular/core';
import { OnChanges } from '@angular/core';
import { Input, Output, EventEmitter } from '@angular/core';
import { Component, ChangeDetectionStrategy, OnInit, Inject } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { takeUntil } from 'rxjs/operators';

// STATSCORE global object to control widget
declare var STATSCORE;
@Component({
  selector: 'hg-statscore',
  templateUrl: './statscore.component.html',
  styleUrls: ['./statscore.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class StatscoreComponent extends DestroySubject implements OnInit, OnChanges, OnDestroy {
  @Input()
  sourceRef: string;

  @Input()
  preEventOrLiveConfigValue: string;

  @Input()
  token: string;

  @Output()
  widgetIsLoaded = new EventEmitter<boolean>();

  @Output()
  close = new EventEmitter();

  loading = false;
  widgetLoaded: boolean;

  public cleanedSourceRef: string;
  public currentLanguage: string;

  script: any;
  trackerGenerator: any;

  constructor(
    private i18nService: I18nService,
    public cdRef: ChangeDetectorRef,
    @Inject(DOCUMENT) private document,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.currentLanguage = this.i18nService.currentLanguageCode;

    if (isPlatformBrowser(this.platformId)) {
      if (!document.querySelector('#STATSCORE_LMP_GENERATOR_SCRIPT')) {
        this.script = this.document.createElement('script');
        this.script.src = 'https://live.statscore.com/livescorepro/generator?auto_init=false';
        this.script.rel = 'script';
        this.script.id = 'STATSCORE_LMP_GENERATOR_SCRIPT';

        this.script.addEventListener('load', () => {
          this.handleTracker();
        });
        this.document.querySelector('body').appendChild(this.script);
      } else {
        this.handleTracker();
      }

      window.addEventListener(`statscore.livematchpro.${this.sourceRef}.ready`, () => {
        this.widgetIsLoaded.emit(true);
        this.widgetLoaded = true;
        this.loading = false;
        this.cdRef.markForCheck();
      });

      window.addEventListener(`statscore.livematchpro.${this.sourceRef}.error`, () => {
        this.widgetIsLoaded.emit(false);
        this.widgetLoaded = false;
        this.loading = false;
        this.cdRef.markForCheck();
      });
    }
  }

  ngOnDestroy(): void {
    if (this.script) {
      this.trackerGenerator.remove();
    }
  }

  handleTracker() {
    this.trackerGenerator = new STATSCORE.LSP.Generator({
      authToken: this.token
    });

    this.trackerGenerator.create(
      this.document.querySelector('#STATSCORE__Tracker'),
      this.sourceRef,
      this.cleanedSourceRef,
      this.preEventOrLiveConfigValue,
      { lang: this.currentLanguage, useMappedId: '1' }
    );

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(cl => {
      if (this.currentLanguage !== cl) {
        var tracker = this.trackerGenerator.get(this.sourceRef);
        this.currentLanguage = cl;
        tracker.setLang(this.currentLanguage).refresh();
      }
    });
  }

  ngOnChanges(_changes: SimpleChanges): void {
    this.cleanedSourceRef = this.sourceRef?.replace(/BR-|LS-/gi, '');
  }
}
