import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  Inject,
  PLATFORM_ID,
  SimpleChanges
} from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { takeUntil } from 'rxjs/operators';

// STATSCORE global object to control widget
declare var STATSCOREWidgets;

@Component({
  selector: 'hg-statscore2',
  templateUrl: './statscore2.component.html',
  styleUrls: ['./statscore2.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Statscore2Component extends DestroySubject implements OnInit, OnChanges, OnDestroy {
  @Input()
  sourceRef: string;

  @Input()
  preEventOrLiveConfigValue: string;

  @Input()
  widgetOverride: string;

  @Output()
  widgetIsLoaded = new EventEmitter<boolean>();

  @Output()
  close = new EventEmitter();

  hasError: boolean;
  loading: boolean;
  widgetLoaded: boolean;
  iFrameSrc: string;

  public cleanedSourceRef: string;
  public currentLanguage: string;

  script: any;
  trackerGenerator: any;

  constructor(
    private i18nService: I18nService,
    public cdRef: ChangeDetectorRef,
    @Inject(DOCUMENT) private document,
    @Inject(PLATFORM_ID) private platformId,
    private sanitizer: DomSanitizer
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.currentLanguage = this.i18nService.currentLanguageCode;

    if (isPlatformBrowser(this.platformId)) {
      if (this.widgetOverride) {
        this.iFrameSrc = this.sanitizer.bypassSecurityTrustResourceUrl(this.widgetOverride) as string;
        this.ready();
      } else if (!document.querySelector('#STATSCORE_LMP_GENERATOR_SCRIPT')) {
        this.script = this.document.createElement('script');
        this.script.src = 'https://wgt-s3-cdn.statscore.com/bundle/Embeder.js';
        this.script.rel = 'script';
        this.script.id = 'STATSCORE_LMP_GENERATOR_SCRIPT';

        this.script.addEventListener('load', () => {
          this.handleTracker();
        });
        this.document.querySelector('body').appendChild(this.script);
      } else {
        this.handleTracker();
      }
    }
  }

  ready() {
    this.widgetLoaded = true;
    this.loading = false;
    this.cdRef.markForCheck();
    this.widgetIsLoaded.emit(true);
  }

  error() {
    this.hasError = true;
    this.widgetLoaded = false;
    this.loading = false;
    this.cdRef.markForCheck();
    this.widgetIsLoaded.emit(false);
  }

  ngOnDestroy(): void {
    if (this.trackerGenerator) {
      this.trackerGenerator.destroy();
    }

    super.ngOnDestroy();
  }

  initializeTrackerGenerator(language: string) {
    const options = {
      loader: {
        enabled: true,
        size: 40,
        color1: this.getColor('primary'),
        color2: this.getColor('accent-bg')
      }
    };
    const inputData = { eventId: 'm:' + this.cleanedSourceRef, language: language };
    this.trackerGenerator = new STATSCOREWidgets.WidgetGroup(
      this.document.getElementById('STATSCORE__Tracker'),
      this.preEventOrLiveConfigValue,
      inputData,
      options
    );
  }

  handleTracker() {
    this.initializeTrackerGenerator(this.currentLanguage);

    this.trackerGenerator.on('load', () => {
      this.ready();
    });

    this.trackerGenerator.on('error', () => {
      this.error();
    });

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(cl => {
      if (this.currentLanguage !== cl) {
        this.currentLanguage = cl;
        this.initializeTrackerGenerator(this.currentLanguage);
      }
    });
  }

  ngOnChanges(_changes: SimpleChanges): void {
    this.cleanedSourceRef = this.sourceRef?.replace(/BR-|LS-/gi, '');
  }

  getColor(name: string) {
    const styles = window.getComputedStyle(
      document.getElementById('statscore2-colors').getElementsByClassName(name)[0]
    );

    return this.hexCode(styles.getPropertyValue('color'));
  }

  hexCode(color: string) {
    const rgba = color.replace(/^rgba?\(|\s+|\)$/g, '').split(',');
    const hex = `#${((1 << 24) + (parseInt(rgba[0]) << 16) + (parseInt(rgba[1]) << 8) + parseInt(rgba[2]))
      .toString(16)
      .slice(1)}`;

    return hex;
  }
}
