import {
  ChangeDetectorRef,
  ElementRef,
  EventEmitter,
  HostListener,
  Inject,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  Component,
  ChangeDetectionStrategy,
  Input
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import {
  BetradarFeatureType,
  OperatorFeatures,
  ScoreWidgetConfiguration,
  ScoreWidgetType
} from '@honoregaming/configuration';
import { hasFlag, LocalStorageService, kioskToken, DestroySubject } from '@honoregaming/core';
import { EventStateType, Match } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { ScoreWidgetWarningDataComponent } from '../score-widget-warning-data/score-widget-warning-data.component';

@Component({
  selector: 'hg-score-widget',
  templateUrl: './score-widget.component.html',
  styleUrls: ['./score-widget.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ScoreWidgetComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() configuration!: ScoreWidgetInputConfiguration;
  @Input() isLive: boolean;
  @Input() sourceRef: string;
  @Input() warnOnDataConsumption: boolean = false;
  @Input() displayTextWarnOnData: boolean = false;
  @Input() isStickyHeader: boolean;
  @Input() event: Match;

  @Output() displayed = new EventEmitter<string>();
  @Output() closed = new EventEmitter<void>();
  @Output() widgetError = new EventEmitter<string>();
  @Output() blockHeight = new EventEmitter<number>();
  @Output() toggleEventHistory = new EventEmitter();

  @ViewChild('blockEventHeight', { read: ElementRef }) set content(content: ElementRef) {
    if (content) {
      this.blockEventElement = content;
      this.onResize();
    }

    this.cdRef.detectChanges();
  }

  blockEventHeight?: number;
  blockEventElement?: ElementRef;

  liveTrackerAvailable: boolean = false;

  scoreWidgetActivated: boolean = false;
  isValidSourceRef: boolean = false;

  preEventOrLiveConfigValue?: string;
  widgetOverride?: string;
  ScoreWidgetType = ScoreWidgetType;
  EventStateType = EventStateType;
  statscoreIsLoaded: boolean = false;

  public isExpired: boolean = false;

  private static readonly EXPIRED_STATES = new Set<EventStateType>([
    EventStateType.Void,
    EventStateType.Postponed,
    EventStateType.Stopped,
    EventStateType.Cancelled,
    EventStateType.Finished,
    EventStateType.Settled
  ]);

  private static readonly INTERNAL_SOURCE_REF_PREFIX = 'HG-';
  private static readonly SCORE_WIDGET_DATA_CONSENT_KEY = 'acceptscorewidgetdata';

  constructor(
    private readonly storageService: LocalStorageService,
    public readonly cdRef: ChangeDetectorRef,
    private readonly messageService: MessageService,
    @Inject(kioskToken) public readonly isKiosk: boolean
  ) {
    super();
  }

  ngOnInit(): void {
    this.liveTrackerAvailable = hasFlag(this.configuration.features.betradarFeatures, BetradarFeatureType.LiveTracker);
    this.preEventOrLiveConfigValue = this.resolveEventConfig();
    this.widgetOverride = this.resolveWidgetOverride();
    this.isExpired = ScoreWidgetComponent.EXPIRED_STATES.has(this.event.state);
    this.isValidSourceRef = this.isSourceRefValid();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes?.isStickyHeader) {
      setTimeout(() => {
        this.onResize();
      }, 0);
    }
  }

  @HostListener('window:resize')
  onResize(): void {
    if (this.blockEventElement) {
      this.blockEventHeight = this.blockEventElement?.nativeElement?.childNodes[0].clientHeight;
      this.blockHeight.emit(this.blockEventHeight);
      this.cdRef.detectChanges();
    }
  }

  statscoreWidgetIsloaded(loaded: boolean): void {
    this.statscoreIsLoaded = loaded;

    if (loaded) {
      this.displayed.emit(this.configuration.scoreWidgetConfiguration.type);
    } else {
      this.widgetError.emit(this.configuration.scoreWidgetConfiguration.type);
    }
  }

  activateScoreWidget(isLive: boolean): void {
    if (this.requiresDataConsumptionWarning()) {
      this.showDataWarningAndActivate(isLive);
    } else {
      this.activateAndRefresh();
    }
  }

  closeScoreWidget(): void {
    this.scoreWidgetActivated = false;
    this.statscoreIsLoaded = false;
    this.closed.emit();
  }

  blockHeaderHeight(height: number): void {
    this.blockEventHeight = height;
    this.blockHeight.emit(this.blockEventHeight);
  }

  private resolveEventConfig(): string | undefined {
    const config: ScoreWidgetConfiguration = this.configuration.scoreWidgetConfiguration?.configuration;
    return this.isLive ? config?.liveConfig : config?.preEventConfig;
  }

  private resolveWidgetOverride(): string | undefined {
    const overrides = this.configuration.scoreWidgetConfiguration?.configuration?.overrides;
    if (!overrides) {
      return undefined;
    }

    if (this.event.eventCategoryId in overrides) {
      return `${overrides[this.event.eventCategoryId]}`;
    }

    return this.resolveWidgetOverrideFromCategoryPath(overrides);
  }

  private resolveWidgetOverrideFromCategoryPath(overrides: Record<number, unknown>): string | undefined {
    const categoryPathIds: number[] = this.parseCategoryPathIds();
    if (!categoryPathIds?.length) {
      return undefined;
    }

    for (let i = categoryPathIds.length - 1; i >= 0; i--) {
      if (categoryPathIds[i] in overrides) {
        return `${overrides[categoryPathIds[i]]}`;
      }
    }

    return undefined;
  }

  private parseCategoryPathIds(): number[] | undefined {
    return this.event.categoryPath
      ?.split('/')
      .map(cat => Number.parseInt(cat, 10))
      .filter(cat => !Number.isNaN(cat));
  }

  private isSourceRefValid(): boolean {
    return !!this.sourceRef?.length && !this.sourceRef.includes(ScoreWidgetComponent.INTERNAL_SOURCE_REF_PREFIX);
  }

  private requiresDataConsumptionWarning(): boolean {
    return (
      this.warnOnDataConsumption &&
      !this.storageService.getItem(ScoreWidgetComponent.SCORE_WIDGET_DATA_CONSENT_KEY) &&
      !this.displayTextWarnOnData
    );
  }

  private showDataWarningAndActivate(isLive: boolean): void {
    this.messageService
      .sendComponentMessage(ScoreWidgetWarningDataComponent, {
        isLive,
        warnOnDataConsumption: this.warnOnDataConsumption
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(result => this.onDataWarningClosed(result));
  }

  private onDataWarningClosed(result: unknown): void {
    if (result == null) {
      return;
    }

    if (this.warnOnDataConsumption) {
      this.storageService.setItem(ScoreWidgetComponent.SCORE_WIDGET_DATA_CONSENT_KEY, result);
    }

    this.activateAndRefresh();
  }

  private activateAndRefresh(): void {
    this.scoreWidgetActivated = true;
    this.cdRef.markForCheck();
  }
}

interface ScoreWidgetInputConfiguration {
  features: OperatorFeatures;
  scoreWidgetConfiguration: {
    enabled: boolean;
    type: ScoreWidgetType;
    configuration: ScoreWidgetConfiguration;
  };
}
